const {test,before,after}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {chromium}=require('playwright');let browser,server,url;const root=path.resolve(__dirname,'..');
const harness=`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="stylesheet" href="/practice-tools.css"><link rel="stylesheet" href="/dental-record.css"><style>body{margin:16px;background:#f5f7fb}</style><main id="root"></main><script src="/dental-record.js"></script><script src="/dental-workflow.js"></script><script>
window.storeImages=(r)=>{r.imageData||={};for(const im of r.body.dentalChart.images||[])if(im.dataUrl){r.imageData[im.id]=im.dataUrl;delete im.dataUrl;im.imageRevision=r.revision;}};window.state={scope:'a:owner',ready:true,medical:true,workflows:[],records:JSON.parse(sessionStorage.getItem('synthetic-records')||'[]'),requests:[],fail:false};window.api=async(p,o={})=>{const s=state;s.requests.push({p,...o});if(s.fail)throw Error('합성 저장 실패');const b=o.body?JSON.parse(o.body):null;if(p.includes('/workflows')){if(o.method==='POST'&&!p.endsWith('/workflows')){const r=s.workflows.find(x=>x.id===p.split('/').pop());if(!r||r.revision!==b.revision)throw Object.assign(Error('최신 문구를 확인해주세요.'),{status:409});r.body=b.body;r.revision++;return {id:r.id,revision:r.revision};}if(o.method==='POST'){const r={id:'phrase'+(s.workflows.length+1),revision:1,body:b.body};s.workflows.push(r);return {id:r.id};}if(o.method==='DELETE'){s.workflows=s.workflows.filter(x=>x.id!==p.split('/').pop());return {ok:true};}return {items:structuredClone(s.workflows)};}if(p.endsWith('/members'))return {members:[{id:'u',display_name:'시험 수의사'},{id:'t',display_name:'시험 테크니션'}],userId:'u'};if(p.startsWith('/patient-directory')&&s.patientPages){const n=Number(new URL('https://test'+p).searchParams.get('page')||1);return s.patientPages[n-1];}if(p.startsWith('/patient-directory'))return {patients:[{id:'p1',name:'합성 환자',species:'dog',breed:'합성 품종',sex:'female',neutered:'yes',birthDate:'2020-05-01',latestWeightKg:5,guardianName:'합성 보호자'}]};if(p.startsWith('/practice/clinical/dental')&&s.dentalPages)return s.dentalPages[new URL('https://test'+p).searchParams.get('cursor')||'first'];if(p.startsWith('/practice/clinical/dental'))return {items:s.records.filter(r=>!r.body.deleted).map(r=>({id:r.id,patient:r.patient,date:r.body.dentalChart.date,species:r.body.species,diagnosis:r.body.dentalChart.diagnosis})),next:null};if(p.startsWith('/practice/clinical/cases?'))return {items:s.records.filter(r=>r.kind==='surgery'),hasMore:false};if(p.endsWith('/cases')&&o.method==='POST'){const r={id:'case'+(s.records.length+1),revision:1,patient_id:b.patientId||'',patient:{name:b.patientId?'합성 환자':b.quickPatient.name,...(!b.patientId?{guardianName:b.quickPatient.guardianName||'',chartNumber:b.quickPatient.chartNumber||''}:{guardianName:'합성 보호자',chartNumber:'TEST-101'})},body:{species:b.species,weight:b.weight,category:'dental',dentalChart:b.dentalChart}};storeImages(r);s.records.push(r);sessionStorage.setItem('synthetic-records',JSON.stringify(s.records));return {id:r.id,revision:1,dentalChart:structuredClone(r.body.dentalChart)};}const id=p.split('/cases/')[1]?.split('/')[0]?.split('?')[0],r=s.records.find(x=>x.id===id);if(o.method==='POST'){if(b.revision!==r.revision)throw Error('다른 직원이 기록했습니다.');if(b.kind==='case.delete')r.body.deleted=true;else {r.body.dentalChart=b.data;r.body.weight=b.data.weight;}r.revision++;storeImages(r);sessionStorage.setItem('synthetic-records',JSON.stringify(s.records));return {id:r.id,revision:r.revision,dentalChart:structuredClone(r.body.dentalChart)};}if(p.endsWith('/sync'))return {revision:r.revision};if(p.includes('/dental-images?')){const imageId=new URL('https://test'+p).searchParams.get('id');return {id:imageId,dataUrl:r.imageData[imageId]};}return {item:structuredClone(r)};};window.view=DentalRecord.mount(document.querySelector('#root'),{ready:()=>state.ready,identity:()=>state.scope,can:()=>true,medical:()=>state.medical,request:api,openSurgery:async(id,patientId)=>{state.openedSurgery={id,patientId};},clinicName:()=> '합성 병원'});view.open();</script></html>`;
before(async()=>{server=http.createServer((req,res)=>{const p=new URL(req.url,'http://local').pathname;if(p==='/'){res.setHeader('Content-Type','text/html; charset=utf-8');return res.end(harness);}const file=path.join(root,p);if(!file.startsWith(root)||!fs.existsSync(file)){res.statusCode=404;return res.end();}res.setHeader('Content-Type',p.endsWith('.css')?'text/css':'application/javascript');res.end(fs.readFileSync(file));});await new Promise(r=>server.listen(0,'127.0.0.1',r));url='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({executablePath:process.env.HQ_TEST_BROWSER||'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});});after(async()=>{await browser?.close();server.closeAllConnections();await new Promise(r=>server.close(r));});
async function page(size={width:1440,height:1000}){const p=await browser.newPage({viewport:size});p.setDefaultTimeout(8000);await p.goto(url);await p.locator('[data-dn=new]').click();return p;}
async function openPrint(p){if(!await p.locator('[data-print-dialog]').evaluate(e=>e.open))await printSettings(p);await p.locator('[data-print-confirm]').click();}
async function openExtras(p){for(const s of ['.dn-anesthesia','.dn-related','.dn-guardian'])if(!await p.locator(s).evaluate(e=>e.open))await p.locator(s+' > summary').click();}
async function fill(p,species='dog',begin=true){await p.locator('[name=quickName]').fill('합성 치과환자');await p.locator('[name=species]').selectOption(species);if(begin){await p.locator('[data-dn=save]').click();await p.waitForFunction(()=>state.records.length>0);}}
test('dental UI registered patient demographics, tooth recording, save/reopen and correction',async()=>{const p=await page();const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.locator('[data-search]').fill('합성');await p.locator('[data-dn=search]').click();await p.locator('[data-pick]').click();await p.locator('[data-dn=save]').click();assert.match(await p.locator('[data-patient-brief]').innerText(),/합성 품종.*중성화 암컷/);assert.equal(await p.locator('[data-tooth]').count(),42);await p.locator('[data-tooth="108"]').click();await p.locator('.dn-grade-details > summary').click();await openGrades(p);await p.locator('[data-grade=gi][data-value="2"]').click();await p.locator('[name=extractionPlan]').check();await p.locator('[name=note]').fill('합성 소견');await p.locator('[data-note=diagnosis]').fill('시험 진단');await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'저장됨'}).waitFor();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.teeth['108'].gi),2);await p.locator('[data-dn=back]').click();await p.locator('[data-record]').click();await p.locator('[data-tooth="108"]').click();assert.equal(await p.locator('[name=note]').inputValue(),'합성 소견');await p.locator('[name=extractionPlan]').uncheck();await p.locator('[name=extracted]').check();await p.locator('[data-dn=save]').click();assert.ok(await p.evaluate(()=>state.records[0].revision>=2));assert.deepEqual(errors,[]);await p.close();});
test('dental responsive chart stays within screen and retains every tooth',async()=>{for(const size of [{width:1600,height:1000},{width:1024,height:900},{width:390,height:844},{width:360,height:780}]){const p=await page(size);await fill(p,'cat');assert.equal(await p.locator('[data-tooth]').count(),30);await p.locator('[data-tooth="409"]').click();await openGrades(p);await p.locator('[data-grade=pd][data-value="2"]').click();assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),JSON.stringify(await p.evaluate(()=>[...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().right>innerWidth).map(e=>[e.tagName,e.className,e.getBoundingClientRect().right]).slice(0,15))));await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:path.join(root,'../dental-'+size.width+'.png'),fullPage:true});await p.close();}});
test('dental failed save preserves draft and patient switch requires explicit abandonment',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="101"]').click();await openGrades(p);await p.locator('[data-grade=gi][data-value="0"]').click();await p.evaluate(()=>state.fail=true);await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'입력은 유지'}).waitFor();assert.equal(await p.locator('[data-grade=gi][data-value="0"]').getAttribute('aria-pressed'),'true');p.once('dialog',d=>d.dismiss());await p.locator('[data-dn=back]').click();assert.equal(await p.locator('[data-tooth]').count(),42);await p.evaluate(()=>{state.scope='other:user';view.sync();});assert.equal(await p.locator('[data-tooth]').count(),0);await p.close();});
test('dental saved print document opens with vector teeth and complete notes',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="104"]').click();await p.locator('[name=fractured]').check();await p.locator('[data-dn=save]').click();const popup=p.waitForEvent('popup');await openPrint(p);const print=await popup;await print.waitForLoadState();assert.equal(await print.locator('svg').count(),42);assert.match(await print.locator('tbody').innerText(),/104.*파절/);await print.pdf({path:path.join(root,'../dental-print.pdf'),preferCSSPageSize:true,printBackground:true});await print.close();await p.close();});
test('dental read-only view does not allow writing or turn missing entries into normal',async()=>{const p=await page();await fill(p,'cat');await p.locator('[data-dn=save]').click();await p.evaluate(()=>{state.medical=false;view.open();});assert.equal(await p.locator('[data-dn=save]').count(),0);await p.locator('[data-tooth="108"]').click();assert.ok(await p.locator('[data-grade=gi]').first().isDisabled());assert.equal(await p.locator('[data-grade=gi][data-value=""]').getAttribute('aria-pressed'),'true');await p.close();});

test('dental saves pending edits before switching practice tabs without discard prompt',async()=>{const p=await page();const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addScriptTag({url:url+'/practice-tools.js'});await p.evaluate(()=>{view.dispose();const a={ready:()=>true,identity:()=>state.scope,patient:()=>null,can:k=>['patients.read','records.read','records.edit'].includes(k),medical:()=>true,request:(p,o)=>p.startsWith('/intakes')?Promise.resolve({items:[],next:null}):api(p,o)};window.practice=PracticeTools.mount(document.querySelector('#root'),a);practice.prepareTab('dental');practice.open();});await p.locator('[data-dn=new]').click();await fill(p,'cat');await p.locator('[data-note=diagnosis]').fill('이동 직전 소견');let dialogs=0;p.on('dialog',async d=>{dialogs++;await d.dismiss();});await p.evaluate(()=>practice.prepareTab('intake'));await p.waitForFunction(()=>practice.route()==='intake');assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.diagnosis),'이동 직전 소견');assert.equal(dialogs,0);assert.deepEqual(errors,[]);await p.close();});

test('tooth categories and optional desktop arch select the same saved findings',async()=>{const p=await page({width:1600,height:1000});await fill(p,'cat');assert.match(await p.locator('.dn-type-legend').innerText(),/Incisor.*절치/);assert.equal(await p.locator('[data-tooth="106"] .dn-tooth-type').innerText(),'P2');await p.locator('[data-view=overview]').click();await p.locator('[data-overview-tooth="106"]').focus();await p.keyboard.press('Enter');assert.match(await p.locator('[data-editor] h3').innerText(),/106.*Premolar/);await openGrades(p);await p.locator('[data-grade=gi][data-value="2"]').click();assert.ok(await p.locator('[data-overview-tooth="106"]').evaluate(e=>e.classList.contains('dn-state-abnormal')));await p.locator('[data-view=teeth]').click();await p.locator('[data-tooth="109"]').click();assert.match(await p.locator('[data-editor] h3').innerText(),/Molar/);await p.locator('[data-tooth="106"]').click();assert.equal(await p.locator('[data-grade=gi][data-value="2"]').getAttribute('aria-pressed'),'true');await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:path.join(root,'../dental-types-desktop.png'),fullPage:true});await p.setViewportSize({width:390,height:844});assert.ok(!await p.locator('[data-overview]').isVisible());assert.equal(await p.locator('[data-tooth]').count(),30);await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:path.join(root,'../dental-types-mobile.png'),fullPage:true});await p.close();});

test('autosave survives refresh, defaults clinician and retains record weight',async()=>{const p=await page();await fill(p);await p.locator('[data-field=weight]').fill('6.3');await p.locator('[data-tooth="101"]').click();await openGrades(p);await p.locator('[data-grade=gi][data-value="1"]').click();await p.waitForFunction(()=>state.records[0]?.body.dentalChart.weight===6.3&&state.records[0]?.body.dentalChart.teeth['101']?.gi===1);assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.saveState),'saved');assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.veterinarian),'시험 수의사');await p.reload();await p.locator('[data-patient-brief]').waitFor();assert.match(await p.locator('[data-patient-brief]').innerText(),/6.3 kg/);await p.locator('[data-tooth="101"]').click();assert.equal(await p.locator('[data-grade=gi][data-value="1"]').getAttribute('aria-pressed'),'true');await p.close();});
test('batch applies selected fields with explicit existing-value preview',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="101"]').click();await openGrades(p);await p.locator('[data-grade=gi][data-value="2"]').click();await p.locator('[data-dn=multi]').click();await p.locator('[data-tooth="101"]').click();await p.locator('[data-tooth="102"]').click();await p.locator('[data-batch-apply]').waitFor();await openGrades(p);await p.locator('[data-grade=gi][data-value="0"]').click();await p.locator('[data-batch-apply]').click();assert.match(await p.locator('[data-batch-preview]').innerText(),/101.*GI 2.*GI 0/);await p.locator('[data-batch-apply]').click();await p.locator('[data-dn=save]').click();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.teeth['101'].gi),0);assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.teeth['102'].gi),0);assert.equal(await p.locator('[data-tooth="102"]').getAttribute('class').then(x=>x.includes('dn-state-partial')),true);await p.close();});
test('mobile sheet preserves chart scroll and supports next tooth',async()=>{const p=await page({width:390,height:844});await fill(p,'cat');await p.locator('[data-tooth="108"]').scrollIntoViewIfNeeded();const y=await p.evaluate(()=>scrollY);await p.locator('[data-tooth="108"]').click();assert.equal(await p.evaluate(()=>scrollY),y);assert.equal(await p.locator('[data-editor]').evaluate(e=>getComputedStyle(e).position),'fixed');await p.locator('[data-step="1"]').click();assert.match(await p.locator('[data-editor] h3').innerText(),/109/);await p.locator('[data-editor-close]').click();assert.ok(!await p.locator('[data-editor]').isVisible());await p.close();});
test('concurrent correction keeps separate fields and resolves same-tooth conflict',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="108"]').click();await openGrades(p);await p.locator('[data-grade=gi][data-value="1"]').click();await p.locator('[data-dn=save]').click();await p.evaluate(()=>{state.records[0].body.dentalChart.teeth['108']={gi:3};state.records[0].body.dentalChart.procedure='다른 직원 처치';state.records[0].revision++;});await openGrades(p);await p.locator('[data-grade=gi][data-value="2"]').click();await p.locator('[data-note=diagnosis]').fill('내 소견');await p.locator('[data-dn=save]').click();await p.locator('.dn-conflict').waitFor();assert.match(await p.locator('.dn-conflict').innerText(),/GI · 치은염[\s\S]*2[\s\S]*3/);await p.locator('[data-conflict="teeth.108.gi"]').selectOption('local');await p.locator('[data-resolve]').click();await p.locator('[data-dn-status]').filter({hasText:'저장됨'}).waitFor();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.teeth['108'].gi),2);assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.procedure),'다른 직원 처치');assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.diagnosis),'내 소견');await p.close();});
test('prior record comparison stays read-only and deletion needs one confirmation',async()=>{const p=await page();await p.locator('[data-search]').fill('합성');await p.locator('[data-dn=search]').click();await p.locator('[data-pick]').click();await p.locator('[data-dn=save]').click();await p.locator('[data-note=diagnosis]').fill('현재 기록');await p.locator('[data-dn=save]').click();await p.evaluate(()=>{const r=structuredClone(state.records[0]);r.id='older';r.body.dentalChart.date='2025-01-01';r.body.dentalChart.diagnosis='이전 소견';state.records.push(r);});await p.locator('[data-dn=prior]').click();await p.locator('[data-prior-choice]').selectOption('older');assert.match(await p.locator('.dn-comparison').innerText(),/이전 소견/);assert.equal(await p.locator('[data-note=diagnosis]').inputValue(),'현재 기록');let count=0;p.once('dialog',async d=>{count++;await d.accept();});await p.locator('[data-dn=delete]').click();await p.locator('[data-dn=new]').waitFor();assert.equal(count,1);assert.equal(await p.locator('[data-record]').count(),1);assert.equal(await p.evaluate(()=>state.records[0].body.deleted),true);await p.close();});
test('record search continues empty scanned pages with explicit more',async()=>{const p=await page();await p.locator('[data-dn=back]').click();await p.evaluate(()=>{const original=api;window.searchReads=[];api=async(p,o)=>{if(p.includes('/dental?')&&p.includes('q=')){searchReads.push(p);return p.includes('cursor=')?{items:[{id:'found',patient:{name:'검색 환자'},date:'2020-01-01',species:'cat',diagnosis:'찾을 소견'}],next:null}:{items:[],next:'older-page'};}return original(p,o);};view.dispose();view=DentalRecord.mount(document.querySelector('#root'),{ready:()=>true,identity:()=>state.scope,can:()=>true,medical:()=>true,request:(p,o)=>api(p,o)});return view.open();});await p.locator('[data-dn-query]').fill('찾을 소견');await p.locator('[data-list-search] button').click();await p.locator('[data-dn=more]').waitFor();assert.equal(await p.evaluate(()=>searchReads.length),1);await p.locator('[data-dn=more]').click();await p.locator('[data-record=found]').waitFor();assert.equal(await p.evaluate(()=>searchReads.length),2);await p.close();});

test('autosave leaves focused mobile editor node and scroll intact',async()=>{const p=await page({width:390,height:844});await fill(p,'cat');await p.locator('[data-tooth="108"]').click();await p.locator('[name=note]').fill('연속 입력 유지');await p.evaluate(()=>{window.originalInput=document.querySelector('[name=note]');originalInput.focus();originalInput.setSelectionRange(3,3);window.editorY=document.querySelector('[data-editor]').scrollTop;});await p.waitForFunction(()=>state.records.length===1);assert.ok(await p.evaluate(()=>originalInput===document.querySelector('[name=note]')&&document.activeElement===originalInput));assert.equal(await p.locator('[data-editor]').evaluate(e=>e.scrollTop),await p.evaluate(()=>editorY));assert.equal(await p.locator('[name=note]').evaluate(e=>e.selectionStart),3);await p.close();});
test('print saves latest dirty text first and does not print after failure',async()=>{const p=await page();await fill(p);await p.locator('[data-note=diagnosis]').fill('마지막 입력 인쇄');let wait=p.waitForEvent('popup');await openPrint(p);let popup=await wait;await popup.waitForLoadState();assert.match(await popup.locator('body').innerText(),/마지막 입력 인쇄/);assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.diagnosis),'마지막 입력 인쇄');await popup.close();await p.locator('[data-note=diagnosis]').fill('저장 실패한 내용');await p.evaluate(()=>state.fail=true);wait=p.waitForEvent('popup');await openPrint(p);popup=await wait;await p.locator('[data-dn-status]').filter({hasText:'저장 실패'}).waitFor();assert.ok(popup.isClosed());assert.equal(await p.locator('[data-note=diagnosis]').inputValue(),'저장 실패한 내용');await p.close();});
test('detailed findings and clinical status persist independently of storage',async()=>{const p=await page();await fill(p);await p.locator('[data-tooth="108"]').click();await p.locator('.dn-tooth-detail').evaluate(e=>e.open=true);await p.locator('[name=mobile]').check();await p.locator('[data-detail=mobilityGrade]').selectOption('2');await p.locator('[data-detail=furcationGrade]').selectOption('1');await p.locator('[data-detail=recessionMm]').fill('2.5');await p.locator('[data-pocket=MB]').fill('4');await p.locator('[name=resorption]').check();await p.locator('[data-detail=resorptionStage]').selectOption('4b');await p.locator('[data-detail=resorptionType]').selectOption('2');await p.locator('[data-complete]').click();await p.locator('[data-dn=save]').click();const saved=await p.evaluate(()=>state.records[0].body.dentalChart);assert.equal(saved.clinicalStatus,'complete');assert.equal(saved.teeth['108'].pockets.MB,4);await p.reload();await p.locator('[data-tooth="108"]').click();await p.locator('.dn-tooth-detail').evaluate(e=>e.open=true);assert.equal(await p.locator('[data-detail=resorptionStage]').inputValue(),'4b');assert.equal(await p.locator('[data-detail=recessionMm]').inputValue(),'2.5');await p.close();});
