test('returning from a record preserves search, loaded pages and list position',async()=>{const p=await page();await fill(p);await p.locator('[data-dn=save]').click();await p.evaluate(()=>{const seed=structuredClone(state.records[0]);state.records=Array.from({length:120},(_,i)=>({...structuredClone(seed),id:'case'+i,patient:{name:'합성 '+i},body:{...structuredClone(seed.body),dentalChart:{...structuredClone(seed.body.dentalChart),diagnosis:'진단 '+i}}}));const original=api;view.dispose();sessionStorage.removeItem('carestep.dental.resume.'+state.scope);view=DentalRecord.mount(document.querySelector('#root'),{ready:()=>true,identity:()=>state.scope,can:()=>true,medical:()=>true,request:async(path,o)=>{if(path.startsWith('/practice/clinical/dental')){const u=new URL('https://test'+path),offset=Number(u.searchParams.get('cursor')||0),found=state.records.filter(r=>!u.searchParams.get('q')||r.body.dentalChart.diagnosis.includes(u.searchParams.get('q')));return {items:found.slice(offset,offset+50).map(r=>({id:r.id,patient:r.patient,date:r.body.dentalChart.date,species:r.body.species,diagnosis:r.body.dentalChart.diagnosis})),next:offset+50<found.length?String(offset+50):null};}return original(path,o);}});view.open();});await p.locator('[data-dn-query]').fill('진단');await p.locator('[data-list-search] button').click();await p.locator('[data-dn=more]').click();assert.equal(await p.locator('[data-record]').count(),100);await p.locator('[data-record="case80"]').scrollIntoViewIfNeeded();const y=await p.evaluate(()=>scrollY);await p.locator('[data-record="case80"]').click();await p.locator('[data-dn=back]').click();await p.waitForFunction(()=>document.querySelectorAll('[data-record]').length===100);assert.equal(await p.locator('[data-dn-query]').inputValue(),'진단');await p.waitForTimeout(50);assert.ok(Math.abs(await p.evaluate(()=>scrollY)-y)<50);await p.close();});

async function saved16(p){await fill(p);await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'저장됨'}).waitFor();}
async function remount16(p){await p.evaluate(async()=>{view.dispose();view=DentalRecord.mount(document.querySelector('#root'),{ready:()=>state.ready,identity:()=>state.scope,can:()=>true,medical:()=>true,request:(p,o)=>api(p,o)});await view.open();});await p.locator('[data-patient-brief]').waitFor();}
async function focus16(p){await p.evaluate(()=>{const old=Date.now;Date.now=()=>old()+20000;window.dispatchEvent(new Event('focus'));});}
