test('photo viewer stays in record and supports zoom rotate navigation and Escape',async()=>{for(const width of [1440,390]){const p=await page({width,height:900});await fill(p);await photos17(p);let popups=0;p.on('popup',()=>popups++);await p.locator('[data-image-open]').first().click();await p.locator('[data-view-photo]').waitFor({state:'visible'});assert.match(await p.locator('[data-view-title]').innerText(),/1 \/ 2/);assert.ok(await p.locator('[data-view-prev]').isDisabled());await p.locator('[data-view-plus]').click();assert.equal(await p.locator('[data-view-scale]').innerText(),'125%');await p.locator('[data-view-rotate]').click();assert.match(await p.locator('[data-view-photo]').getAttribute('style'),/rotate\(90deg\)/);await p.locator('[data-view-next]').click();assert.match(await p.locator('[data-view-title]').innerText(),/2 \/ 2/);assert.equal(await p.locator('[data-view-scale]').innerText(),'100%');assert.ok(await p.locator('[data-view-next]').isDisabled());await p.locator('[data-view-photo]').waitFor({state:'visible'});assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.screenshot({path:path.join(root,'../dental17-viewer-'+width+'.png')});await p.keyboard.press('Escape');assert.equal(await p.locator('[data-photo-viewer]').count(),0);assert.equal(popups,0);await p.close();}});
test('pinned patient context stays visible when scrolling and updates edited demographics',async()=>{for(const width of [1440,390]){const p=await page({width,height:900});await fill(p);await p.locator('.dn-patient-details > summary').click();await p.locator('[data-field="patient.breed"]').fill('시험 품종');await p.locator('[data-sex]').selectOption('male:yes');await p.locator('[data-field="patient.birthDate"]').fill('2020-01-01');await p.evaluate(()=>scrollTo(0,document.body.scrollHeight));const pinned=p.locator('[data-pinned-patient]');assert.match(await pinned.innerText(),/합성 치과환자.*시험 품종.*중성화 수컷/s);assert.ok(await pinned.evaluate(e=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<innerHeight;}));await p.screenshot({path:path.join(root,'../dental17-pinned-'+width+'.png')});await p.close();}});
test('reconnection retries the same save request and then persists newer input',async()=>{const p=await page();await saved16(p);await p.evaluate(()=>state.fail=true);await p.locator('[data-note=diagnosis]').fill('첫 입력');await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'저장 실패'}).waitFor();await p.locator('[data-note=procedure]').fill('실패 후 추가 입력');await p.evaluate(()=>{state.fail=false;dispatchEvent(new Event('online'));});await p.waitForFunction(()=>state.records[0].body.dentalChart.procedure==='실패 후 추가 입력');const reqs=await p.evaluate(()=>state.requests.filter(r=>r.method==='POST'&&r.p.endsWith('/events')).map(r=>JSON.parse(r.body)));assert.equal(reqs[0].requestKey,reqs[1].requestKey);assert.notEqual(reqs[1].requestKey,reqs.at(-1).requestKey);assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.diagnosis),'첫 입력');await p.close();});
test('connection recovery does not repeat validation or authorization errors',async()=>{const p=await page();await saved16(p);await p.evaluate(()=>{const orig=api;window.denied=0;api=async(p,o)=>{if(o?.method==='POST'){denied++;throw Object.assign(Error('접근 거부'),{status:403});}return orig(p,o);};});await remount16(p);await p.locator('[data-note=diagnosis]').fill('입력 보존');await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'저장 실패'}).waitFor();await p.evaluate(()=>dispatchEvent(new Event('online')));await p.waitForTimeout(2300);assert.equal(await p.evaluate(()=>denied),1);assert.equal(await p.locator('[data-note=diagnosis]').inputValue(),'입력 보존');await p.close();});
test('periodic refresh skips hidden screens and leaves unchanged input nodes intact',async()=>{const p=await page();await saved16(p);await p.evaluate(()=>{const orig=window.setInterval;window.setInterval=(fn,ms,...args)=>{if(ms===30000)window.dentalPoll=fn;return orig(fn,ms,...args);};});await remount16(p);const before=await p.evaluate(()=>{window.originalDiagnosis=document.querySelector('[data-note=diagnosis]');document.querySelector('#root').style.display='none';return state.requests.length;});await p.evaluate(()=>{const d=Date.now;Date.now=()=>d()+31000;dentalPoll();});await p.waitForTimeout(80);assert.equal(await p.evaluate(()=>state.requests.length),before);await p.evaluate(()=>{document.querySelector('#root').style.display='';dentalPoll();});await p.waitForTimeout(80);assert.ok(await p.evaluate(()=>document.querySelector('[data-note=diagnosis]')===originalDiagnosis));await p.evaluate(()=>{state.records[0].body.dentalChart.diagnosis='원격 새 기록';state.records[0].revision++;const d=Date.now;Date.now=()=>d()+31000;dentalPoll();});await p.waitForFunction(()=>document.querySelector('[data-note=diagnosis]').value==='원격 새 기록');await p.close();});
test('print preferences survive refresh, quick print skips dialog and accounts stay isolated',async()=>{const p=await page();await saved16(p);await printSettings(p);await p.locator('[data-print-mode]').selectOption('detailed');await p.locator('[data-print-images]').check();let wait=p.waitForEvent('popup');await p.locator('[data-print-confirm]').click();let pop=await wait;await pop.waitForLoadState();await pop.close();assert.equal(await p.locator('[data-dn=quick-print]').count(),1);await p.reload();await p.locator('[data-dn=quick-print]').waitFor();wait=p.waitForEvent('popup');await p.locator('[data-dn=quick-print]').click();pop=await wait;await pop.waitForLoadState();assert.equal(await p.locator('[data-print-dialog]').evaluate(e=>e.open),false);await pop.close();await printSettings(p);assert.equal(await p.locator('[data-print-mode]').inputValue(),'detailed');assert.equal(await p.locator('[data-print-images]').isChecked(),true);await p.locator('[data-print-cancel]').click();await p.evaluate(async()=>{state.scope='other:user';view.sync();await view.open();});await p.locator('[data-dn=new]').click();assert.equal(await p.locator('[data-dn=quick-print]').count(),0);await p.close();});


test('single patient identity and workflow jumps preserve notes on PC and mobile',async()=>{for(const width of [1440,390]){const p=await page({width,height:900});await fill(p);assert.equal(await p.locator('.dn-patient').count(),0);assert.equal(await p.locator('[data-patient-brief]').count(),1);assert.equal(await p.locator('[data-section-jump]').count(),4);await p.locator('[data-note=diagnosis]').fill('이동해도 유지되는 소견');await p.locator('[data-section-jump=photos]').click();assert.ok(await p.locator('.dn-related').evaluate(e=>e.open));await p.locator('[data-section-jump=notes]').click();assert.equal(await p.locator('[data-note=diagnosis]').inputValue(),'이동해도 유지되는 소견');await p.locator('[data-section-jump=finish]').click();assert.ok(await p.locator('[data-complete]').isVisible());await p.locator('[data-section-jump=teeth]').click();await p.waitForTimeout(100);assert.ok(await p.locator('[data-pinned-patient]').evaluate(e=>{const b=e.getBoundingClientRect();return b.top>=0&&b.bottom<innerHeight;}),JSON.stringify(await p.evaluate(()=>({y:scrollY,h:document.body.scrollHeight,root:document.querySelector('#root').getBoundingClientRect().toJSON(),head:document.querySelector('.dn-head').getBoundingClientRect().toJSON()}))));assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await p.screenshot({path:path.join(root,'../dental18-navigation-'+width+'.png')});await p.close();}});
test('tooth number jump respects species, leaves entered findings and exits batch filters',async()=>{const p=await page();await fill(p,'cat');await p.locator('[data-tooth="108"]').click();await p.locator('[name=note]').fill('보존할 소견');await p.locator('[data-tooth-number]').fill('105');await p.locator('[data-tooth-number]').press('Enter');assert.equal(await p.locator('[data-tooth-number]').getAttribute('aria-invalid'),'true');assert.match(await p.locator('[data-editor] h3').innerText(),/108/);await p.locator('[data-dn=multi]').click();await p.locator('[data-tooth-number]').fill('409');await p.locator('[data-tooth-number]').press('Enter');assert.match(await p.locator('[data-editor] h3').innerText(),/409/);assert.equal(await p.locator('[data-dn=multi]').getAttribute('aria-pressed'),'false');await p.locator('[data-tooth-number]').fill('108');await p.locator('[data-tooth-number]').press('Enter');assert.equal(await p.locator('[name=note]').inputValue(),'보존할 소견');await p.close();});
test('print options defer new and in-flight remote refresh until dialog closes',async()=>{const p=await page();await saved16(p);await p.evaluate(()=>{const orig=api;window.delay18=false;api=async(path,o)=>{const r=await orig(path,o);if(delay18&&path.includes('/case1?view=dental')&&o?.method==='GET'){await new Promise(resolve=>window.release18=resolve);}return r;};});await remount16(p);await p.evaluate(()=>{state.records[0].revision++;state.records[0].body.dentalChart.diagnosis='갱신된 진단';delay18=true;});await focus16(p);await p.waitForFunction(()=>typeof release18==='function');await printSettings(p);await p.locator('[data-print-mode]').selectOption('detailed');await p.evaluate(()=>{delay18=false;release18();});await p.waitForTimeout(100);assert.ok(await p.locator('[data-print-dialog]').evaluate(e=>e.open));assert.equal(await p.locator('[data-print-mode]').inputValue(),'detailed');assert.notEqual(await p.locator('[data-note=diagnosis]').inputValue(),'갱신된 진단');const n=await p.evaluate(()=>state.requests.length);await focus16(p);await p.waitForTimeout(400);assert.equal(await p.evaluate(()=>state.requests.length),n);await p.locator('[data-print-cancel]').click();await p.waitForFunction(()=>document.querySelector('[data-note=diagnosis]').value==='갱신된 진단');await p.close();});
test('photo state distinguishes unsaved preparation, server failure and completed storage',async()=>{const p=await page();await fill(p);await photos17(p,1);assert.match(await p.locator('[data-image-save]').innerText(),/저장 대기/);assert.doesNotMatch(await p.locator('[data-image-jobs]').innerText(),/등록됨/);await p.evaluate(()=>state.fail=true);await p.locator('[data-dn=save]').click();await p.locator('[data-dn-status]').filter({hasText:'저장 실패'}).waitFor();assert.match(await p.locator('[data-image-save]').innerText(),/저장 실패/);assert.match(await p.locator('[data-image-jobs]').innerText(),/저장 실패/);await p.evaluate(()=>state.fail=false);await p.locator('[data-dn=save]').click();assert.equal(await p.locator('[data-image-save]').innerText(),'저장 완료');assert.match(await p.locator('[data-image-jobs]').innerText(),/저장 완료/);await p.close();});
async function asymmetricPhoto18(p){const data=await p.evaluate(()=>{const c=document.createElement('canvas');c.width=80;c.height=40;const x=c.getContext('2d');x.fillStyle='red';x.fillRect(0,0,40,40);x.fillStyle='blue';x.fillRect(40,0,40,40);return c.toDataURL('image/png').split(',')[1];});await openExtras(p);await p.locator('[data-image-file]').setInputFiles({name:'회전 시험.png',mimeType:'image/png',buffer:Buffer.from(data,'base64')});await p.locator('[data-image-list] img').waitFor();await p.locator('[data-dn=save]').click();}
test('saved rotation persists dimensions on reopen and print without duplicate images',async()=>{const p=await page();await fill(p);await asymmetricPhoto18(p);const old=await p.evaluate(()=>state.records[0].body.dentalChart.images[0].id);await p.locator('[data-image-open]').click();await p.locator('[data-view-photo]').waitFor({state:'visible'});assert.ok(await p.locator('[data-view-save-rotation]').isDisabled());await p.locator('[data-view-rotate]').click();await p.locator('[data-view-save-rotation]').click();await p.waitForFunction(old=>state.records[0].body.dentalChart.images[0].id!==old,old);await p.waitForFunction(()=>{const i=document.querySelector('[data-view-photo]');return i&&!i.hidden&&i.naturalWidth===40&&i.naturalHeight===80;});assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.images.length),1);await p.keyboard.press('Escape');await p.reload();await openExtras(p);await p.locator('[data-image-open]').click();await p.locator('[data-view-photo]').waitFor({state:'visible'});assert.deepEqual(await p.locator('[data-view-photo]').evaluate(i=>[i.naturalWidth,i.naturalHeight]),[40,80]);await p.keyboard.press('Escape');await printSettings(p);await p.locator('[data-print-images]').check();const wait=p.waitForEvent('popup');await p.locator('[data-print-confirm]').click();const out=await wait;await out.waitForLoadState();assert.deepEqual(await out.locator('img').first().evaluate(i=>[i.naturalWidth,i.naturalHeight]),[40,80]);await out.close();await p.close();});
test('rotation failure keeps rotated draft for retry and read-only viewer cannot save rotation',async()=>{const p=await page();await fill(p);await asymmetricPhoto18(p);const old=await p.evaluate(()=>state.records[0].body.dentalChart.images[0].id);await p.locator('[data-image-open]').click();await p.locator('[data-view-photo]').waitFor({state:'visible'});await p.locator('[data-view-rotate]').click();await p.evaluate(()=>state.fail=true);await p.locator('[data-view-save-rotation]').click();await p.locator('[data-dn-status]').filter({hasText:'저장 실패'}).waitFor();assert.equal(await p.evaluate(()=>state.records[0].body.dentalChart.images[0].id),old);await p.keyboard.press('Escape');assert.match(await p.locator('[data-image-save]').innerText(),/저장 실패/);await p.evaluate(()=>state.fail=false);await p.locator('[data-dn=save]').click();assert.notEqual(await p.evaluate(()=>state.records[0].body.dentalChart.images[0].id),old);await p.evaluate(async()=>{state.medical=false;await view.open();});await openExtras(p);await p.locator('[data-image-open]').click();await p.locator('[data-view-photo]').waitFor({state:'visible'});assert.equal(await p.locator('[data-view-save-rotation]').count(),0);await p.close();});

test('dental19 composition defers remote refresh and autosave until Korean input completes',async()=>{const p=await page();await saved16(p);await p.evaluate(()=>{window.originalField=document.querySelector('[data-note=diagnosis]');originalField.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));state.records[0].body.dentalChart.procedure='Remote synthetic procedure';state.records[0].revision++;});await p.locator('[data-note=diagnosis]').fill('한글 작성 중');await focus16(p);await p.waitForTimeout(2100);assert.equal(await p.evaluate(()=>originalField===document.querySelector('[data-note=diagnosis]')),true);assert.equal(await p.locator('[data-note=procedure]').inputValue(),'');await p.evaluate(()=>originalField.dispatchEvent(new CompositionEvent('compositionend',{bubbles:true})));await p.waitForFunction(()=>document.querySelector('[data-note=procedure]').value==='Remote synthetic procedure');assert.equal(await p.locator('[data-note=diagnosis]').inputValue(),'한글 작성 중');await p.close();});
test('dental19 background query failure leaves saved status and save button unchanged',async()=>{const p=await page();await saved16(p);await remount16(p);const status=await p.locator('[data-dn-status]').innerText(),button=await p.locator('[data-dn=save]').innerText();await p.evaluate(()=>{const original=api;api=async(p,o)=>{if(p.includes('/cases/')&&(!o||o.method==='GET'))throw Error('Synthetic fetch failure');return original(p,o);};});await focus16(p);await p.locator('[data-dn-status]').filter({hasText:'최신 기록 확인 실패'}).waitFor();assert.ok((await p.locator('[data-dn-status]').innerText()).includes(status));assert.equal(await p.locator('[data-dn=save]').innerText(),button);await p.close();});
test('dental19 tooth jump retains notes and photo nodes and clears batch mode without full render',async()=>{const p=await page();await fill(p);await p.locator('[data-note=diagnosis]').fill('Retain synthetic input');await p.locator('[data-dn=multi]').click();await p.evaluate(()=>{window.notesNode=document.querySelector('[data-note=diagnosis]');window.photoNode=document.querySelector('[data-record-section=photos]');});await p.locator('[data-tooth-number]').fill('208');await p.locator('[data-tooth-jump] button').click();assert.equal(await p.evaluate(()=>notesNode===document.querySelector('[data-note=diagnosis]')&&photoNode===document.querySelector('[data-record-section=photos]')),true);assert.match(await p.locator('[data-editor]').innerText(),/208/);assert.equal(await p.locator('[data-dn=batch-open]').count(),0);assert.equal(await p.locator('[data-dn=multi]').getAttribute('aria-pressed'),'false');await p.close();});
