for(const accept of [false,true])test('dental list delete confirmation '+accept,async()=>{
 const p=await page();try{await fill(p);await p.locator('[data-dn=save]').click();await p.waitForFunction(()=>state.records.length===1);await p.locator('[data-dn=back]').click();await p.locator('[data-list-delete]').waitFor();
 p.once('dialog',async d=>{assert.match(d.message(),/합성 치과환자.*치과기록/);await (accept?d.accept():d.dismiss());});await p.locator('[data-list-delete]').click();
 if(accept)await p.waitForFunction(()=>state.records[0].body.deleted);
 await p.waitForFunction(()=>!document.querySelector('[data-list-delete]')?.disabled);
 assert.equal(await p.locator('[data-record]').count(),accept?0:1);
 assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.body&&JSON.parse(r.body).kind==='case.delete').length),accept?1:0);
 }finally{await p.close();}
});
