test('dental quick guardian and chart persist through save list reopen and print',async()=>{
 const p=await page();try{await fill(p,'dog',false);await p.locator('[name=quickGuardianName]').fill('빠른 보호자');await p.locator('[name=quickChartNumber]').fill('QUICK-202');await p.locator('[data-dn=save]').click();await p.waitForFunction(()=>state.records.length===1);assert.match(await p.locator('[data-patient-brief]').innerText(),/빠른 보호자.*QUICK-202/);
 const body=await p.evaluate(()=>JSON.parse(state.requests.find(r=>r.method==='POST'&&r.p.endsWith('/cases')).body));assert.equal(body.quickPatient.guardianName,'빠른 보호자');assert.equal(body.quickPatient.chartNumber,'QUICK-202');assert.equal(body.patientId,undefined);
 await p.locator('[data-dn=back]').click();await p.locator('[data-record]').waitFor();assert.match(await p.locator('[data-record]').innerText(),/빠른 보호자.*QUICK-202/);await p.locator('[data-record]').click();assert.match(await p.locator('[data-patient-brief]').innerText(),/빠른 보호자.*QUICK-202/);
 assert.match(await p.evaluate(()=>DentalRecord.printHtml(state.records[0],state.records[0].body.dentalChart)),/빠른 보호자.*QUICK-202/);
 }finally{await p.close();}
});


