test('compact workflow unchanged record checks revision without fetching full detail',async()=>{
 const p=await page();try{await fill(p);await p.locator('[data-dn=back]').click();await p.locator('[data-record]').click();await p.evaluate(()=>{state.requests=[];const now=Date.now;Date.now=()=>now()+20000;window.dispatchEvent(new Event('focus'));});await p.waitForFunction(()=>state.requests.some(r=>r.p.endsWith('/sync')));assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.p.includes('/cases/')&&!r.p.endsWith('/sync')).length),0);
 }finally{await p.close();}
});

